1	// Package bench times the Vulkan compute kernels in shaders/ across the
2	// "flavours" (naive/tiled/subgroup/cooperative-matrix; fp32/fp16/int8/int4
3	// weights) that matter for neural-network inference, using GPU-side
4	// timestamp queries (vk.ComputePipeline.DispatchTimed) rather than
5	// wall-clock time.
6	package bench
7	
8	import (
9		"fmt"
10		"io"
11		"math/rand"
12		"os"
13		"strings"
14		"text/tabwriter"
15	
16		"strix-halo-vulkan/vk"
17	)
18	
19	// Result is one measured data point.
20	type Result struct {
21		Op           string
22		Variant      string
23		WeightFormat string // "fp32", "fp16", "q8", "q4", or "" if not applicable
24		BlockSize    int    // quantization block size, 0 if not applicable
25		Size         int    // case-defined primary size (vector/matrix dimension)
26		// Detail is an optional free-form description of anything else that
27		// distinguishes this case (e.g. the fixed dimension of a non-square
28		// shape). Must contain no commas, since it becomes a CSV field.
29		Detail    string
30		NsPerIter float64
31		GFLOPS    float64 // 0 if not a compute-bound op
32		GBPS      float64 // 0 if not a bandwidth-bound op
33		// Clocks records the GPU's shader clock and power draw while this
34		// measurement ran. Zero when no instrumentation was installed (see
35		// SetInstruments). Without it a result taken at the 636 MHz idle clock
36		// is indistinguishable from a slow kernel measured at 2900 MHz.
37		Clocks ClockStats
38	}
39	
40	// maxBatchNs bounds how long any single DispatchTimed call (a batch of
41	// back-to-back dispatches recorded into one command buffer) is allowed to
42	// run. Slow kernels (e.g. naive GEMM at large N) can take seconds per
43	// iteration; batching a fixed iteration count regardless of that risks
44	// exceeding the kernel driver's GPU-hang watchdog (amdgpu's default TDR is
45	// commonly ~10s) and getting VK_ERROR_DEVICE_LOST, which poisons the device
46	// for every case still to run. 500ms leaves ample margin under that.
47	const maxBatchNs = 500_000_000
48	
49	// TimeDispatch measures nanoseconds/iteration for one dispatch shape. It
50	// first probes with a single iteration (which also serves as one warmup
51	// dispatch) to estimate per-iteration cost, then caps both the remaining
52	// warmup dispatches and the timed batch to maxBatchNs worth of iterations —
53	// so a very slow kernel is measured with fewer iterations rather than
54	// risking a driver timeout.
55	//
56	// If instrumentation is installed (SetInstruments), the GPU is first driven
57	// with ALU-heavy work to lift it off its idle clock, and the shader clock
58	// and power are sampled throughout the timed batch and returned alongside
59	// the timing. Both steps exist because this part idles at 636 MHz of a
60	// 2900 MHz maximum, so an un-warmed measurement can understate a kernel by
61	// several times — and silently, unless the clock is recorded with it.
62	func TimeDispatch(pipe *vk.ComputePipeline, groupsX, groupsY, groupsZ, warmup, iters uint32, pushConstants []byte) (float64, ClockStats, error) {
63		if err := instruments.Warm(); err != nil {
64			return 0, ClockStats{}, fmt.Errorf("clock warmup: %w", err)
65		}
66		probe, err := pipe.DispatchTimed(groupsX, groupsY, groupsZ, 1, pushConstants)
67		if err != nil {
68			return 0, ClockStats{}, err
69		}
70		probeNs := float64(probe.Nanoseconds())
71		if probeNs <= 0 {
72			probeNs = 1
73		}
74		capToBudget := func(n uint32) uint32 {
75			maxByBudget := uint32(maxBatchNs / probeNs)
76			if maxByBudget < 1 {
77				maxByBudget = 1
78			}
79			if n > maxByBudget {
80				return maxByBudget
81			}
82			return n
83		}
84	
85		if warmup > 1 {
86			if _, err := pipe.DispatchTimed(groupsX, groupsY, groupsZ, capToBudget(warmup-1), pushConstants); err != nil {
87				return 0, ClockStats{}, err
88			}
89		}
90		actualIters := capToBudget(iters)
91		stop := instruments.Watch()
92		d, err := pipe.DispatchTimed(groupsX, groupsY, groupsZ, actualIters, pushConstants)
93		clocks := stop()
94		if err != nil {
95			return 0, ClockStats{}, err
96		}
97		return float64(d.Nanoseconds()) / float64(actualIters), clocks, nil
98	}
99	
100	// TimeDispatchSequence is TimeDispatch for a sequence of dispatches that
101	// differ in their push constants — IDEAS §3.5's one-dispatch-per-expert
102	// baseline. One "iteration" is the whole sequence, so the returned
103	// nanoseconds are per *sequence*, which is what the grouped kernel's single
104	// dispatch is being compared against.
105	//
106	// The budget cap works the same way, and matters more here: a 512-dispatch
107	// sequence recorded 70 times is 36000 commands in one command buffer, and
108	// the probe is what keeps that from becoming a driver timeout on a shape
109	// that turns out to be slow.
110	func TimeDispatchSequence(pipe *vk.ComputePipeline, groupsX []uint32, groupsY, groupsZ, warmup, iters uint32, pushConstants [][]byte) (float64, ClockStats, error) {
111		if err := instruments.Warm(); err != nil {
112			return 0, ClockStats{}, fmt.Errorf("clock warmup: %w", err)
113		}
114		probe, err := pipe.DispatchSequenceTimed(groupsX, groupsY, groupsZ, 1, pushConstants)
115		if err != nil {
116			return 0, ClockStats{}, err
117		}
118		probeNs := float64(probe.Nanoseconds())
119		if probeNs <= 0 {
120			probeNs = 1
121		}
122		capToBudget := func(n uint32) uint32 {
123			maxByBudget := uint32(maxBatchNs / probeNs)
124			if maxByBudget < 1 {
125				maxByBudget = 1
126			}
127			if n > maxByBudget {
128				return maxByBudget
129			}
130			return n
131		}
132	
133		if warmup > 1 {
134			if _, err := pipe.DispatchSequenceTimed(groupsX, groupsY, groupsZ, capToBudget(warmup-1), pushConstants); err != nil {
135				return 0, ClockStats{}, err
136			}
137		}
138		actualIters := capToBudget(iters)
139		stop := instruments.Watch()
140		d, err := pipe.DispatchSequenceTimed(groupsX, groupsY, groupsZ, actualIters, pushConstants)
141		clocks := stop()
142		if err != nil {
143			return 0, ClockStats{}, err
144		}
145		return float64(d.Nanoseconds()) / float64(actualIters), clocks, nil
146	}
147	
148	// PrintTable writes a human-readable results table to w.
149	func PrintTable(w io.Writer, results []Result) {
150		tw := tabwriter.NewWriter(w, 0, 4, 2, ' ', 0)
151		fmt.Fprintln(tw, "OP\tVARIANT\tFORMAT\tBLOCK\tSIZE\tNS/ITER\tGFLOP/S\tGB/S\tSCLK MHZ\tW")
152		for _, r := range results {
153			gflops, gbps, block, sclk, power := "-", "-", "-", "-", "-"
154			if r.GFLOPS > 0 {
155				gflops = fmt.Sprintf("%.2f", r.GFLOPS)
156			}
157			if r.GBPS > 0 {
158				gbps = fmt.Sprintf("%.2f", r.GBPS)
159			}
160			if r.BlockSize > 0 {
161				block = fmt.Sprintf("%d", r.BlockSize)
162			}
163			if r.Clocks.Samples > 0 {
164				// min/max as well as mean: a wide spread means the clock moved
165				// during the measurement, which invalidates the comparison
166				// rather than merely annotating it.
167				sclk = fmt.Sprintf("%.0f (%.0f-%.0f)", r.Clocks.SclkMHz, r.Clocks.SclkMinMHz, r.Clocks.SclkMaxMHz)
168				power = fmt.Sprintf("%.1f", r.Clocks.PowerW)
169			}
170			fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%d\t%.1f\t%s\t%s\t%s\t%s\n",
171				r.Op, r.Variant, r.WeightFormat, block, r.Size, r.NsPerIter, gflops, gbps, sclk, power)
172		}
173		tw.Flush()
174	}
175	
176	// WriteCSV writes results to path as
177	// op,variant,weight_format,block_size,size,ns_per_iter,gflops,gbps
178	// followed by sclk_mhz,sclk_mhz_min,sclk_mhz_max,power_w (zero when no
179	// instrumentation was installed) and detail. The new columns are appended
180	// rather than interleaved so existing column-indexed analysis of the first
181	// eight keeps working.
182	func WriteCSV(path string, results []Result) error {
183		f, err := os.Create(path)
184		if err != nil {
185			return err
